exercises.starter:
function countByType(roster) {
  // tally records into a {type: count} object
}

exercises.solution:
function countByType(roster) {
  const counts = {}
  for (const p of roster) {
    counts[p.type] = (counts[p.type] || 0) + 1
  }
  return counts
}

exercises.starter:
function totalAttackOfType(roster, type) {
  // sum attack across records of the given type
}

exercises.solution:
function totalAttackOfType(roster, type) {
  return roster
    .filter(p => p.type === type)
    .reduce((sum, p) => sum + p.attack, 0)
}

exercises.starter:
function strongestByType(roster) {
  // map each type to the name of its highest-attack record
}

exercises.solution:
function strongestByType(roster) {
  const best = {}
  for (const p of roster) {
    if (!(p.type in best) || p.attack > best[p.type].attack) best[p.type] = p
  }
  const result = {}
  for (const type of Object.keys(best)) result[type] = best[type].name
  return result
}

exercises.starter:
function averageAttackByType(roster) {
  // map each type to its rounded average attack
}

exercises.solution:
function averageAttackByType(roster) {
  const sums = {}
  const counts = {}
  for (const p of roster) {
    sums[p.type] = (sums[p.type] || 0) + p.attack
    counts[p.type] = (counts[p.type] || 0) + 1
  }
  const result = {}
  for (const type of Object.keys(sums)) {
    result[type] = Math.round(sums[type] / counts[type])
  }
  return result
}

exercises.starter:
function topByAttack(roster, n) {
  // return the n highest-attack names, strongest first
}

exercises.solution:
function topByAttack(roster, n) {
  return [...roster]
    .sort((a, b) => b.attack - a.attack)
    .slice(0, n)
    .map(p => p.name)
}

exercises.starter:
function typesWithDefenseAbove(roster, d) {
  // return the distinct qualifying types, sorted
}

exercises.solution:
function typesWithDefenseAbove(roster, d) {
  return [...new Set(roster.filter(p => p.defense > d).map(p => p.type))].sort()
}

exercises.starter:
function typeWithHighestAverageAttack(roster) {
  // return the type with the greatest average attack
}

exercises.solution:
function typeWithHighestAverageAttack(roster) {
  const sums = {}
  const counts = {}
  for (const p of roster) {
    sums[p.type] = (sums[p.type] || 0) + p.attack
    counts[p.type] = (counts[p.type] || 0) + 1
  }
  let best = null
  let bestAvg = -Infinity
  for (const type of Object.keys(sums).sort()) {
    const avg = sums[type] / counts[type]
    if (avg > bestAvg) {
      bestAvg = avg
      best = type
    }
  }
  return best
}

exercises.starter:
function biggestAttackDefenseGap(roster) {
  // return the name of the record with the largest attack - defense gap
}

exercises.solution:
function biggestAttackDefenseGap(roster) {
  let best = null
  for (const p of roster) {
    if (best === null || p.attack - p.defense > best.attack - best.defense) best = p
  }
  return best === null ? null : best.name
}

exercises.starter:
function namesByTypeAbove(roster, minAttack) {
  // group the qualifying names into a {type: [name, ...]} object
}

exercises.solution:
function namesByTypeAbove(roster, minAttack) {
  const groups = {}
  for (const p of roster) {
    if (p.attack >= minAttack) (groups[p.type] ||= []).push(p.name)
  }
  return groups
}
